81	  readonly email: string;
82	  readonly activeOrgId: OrgId | null;
83	  readonly expiresAt: IsoTimestamp;
84	}
85	
86	/** True when `role` is at least as privileged as `atLeast`. */
87	export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
88	  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
