async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  switch (kind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      if (!issue) return orgPath(orgSlug);
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return orgPath(orgSlug);
      return issuePath(orgSlug, project.slug, issue.number);
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      if (!comment) return orgPath(orgSlug);
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      if (!issue) return orgPath(orgSlug);
      const project = await projectRepo.findProjectById(orgId, issue.projectId);
      if (!project) return orgPath(orgSlug);
      return issuePath(orgSlug, project.slug, issue.number);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      if (!project) return orgPath(orgSlug);
      return projectPath(orgSlug, project.slug);
    }
  }
}

