let registered = false;

/** Resolves an issue's link, falling back to the org root if it vanished. */
async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!org || !issue) return "/";

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return "/";

  return issuePath(org.slug, project.slug, issue.number);
}

/**
 * Only recipients without a still-unread alert for the same resource get a
 * new row; once that one is read, the next breach starts a fresh alert.
 */
async function notifyPlanLimit(
  orgId: OrgId,
  resource: string,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<void> {
  const fresh: UserId[] = [];
  for (const recipientId of recipients) {
    const unread = await notificationRepo.listUnreadByKind(
      orgId,
      recipientId,
      "plan_limit_reached",
    );
    if (unread.some((n) => n.body.includes(resource))) continue;
    fresh.push(recipientId);
  }
  await notify(orgId, "plan_limit_reached", fresh, payload);
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    const href = await issueHref(payload.orgId, payload.issueId);
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    const href = await issueHref(payload.orgId, payload.issueId);
