1	/**
2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { assertCan } from "@/lib/permissions";
9	import { assertOrgScope } from "@/lib/tenant";
10	import { issuePath, settingsPath } from "@/lib/url";
11	import * as issueRepo from "@/server/repositories/issue-repository";
12	import * as memberRepo from "@/server/repositories/member-repository";
13	import * as notificationRepo from "@/server/repositories/notification-repository";
14	import * as orgRepo from "@/server/repositories/organization-repository";
15	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
16	import * as projectRepo from "@/server/repositories/project-repository";
17	import { toIsoTimestamp } from "@/types/common";
18	import { notificationResource, requireFound } from "./_support";
19	import type {
20	  ListNotificationsInput,
21	  MarkNotificationReadInput,
22	  UpdateNotificationPreferenceInput,
23	} from "@/schemas/notification";
24	import type { IssueId, OrgId, Page, UserId } from "@/types/common";
25	import type { FlagContext } from "@/types/feature-flag";
26	import type { Actor } from "@/types/member";
27	import type {
28	  Notification,
29	  NotificationChannel,
30	  NotificationKind,
31	  NotificationPreference,
32	} from "@/types/notification";
33	
34	export type NotificationPayload = {
35	  title: string;
36	  body: string;
37	  href: string;
38	  actorId: UserId | null;
39	};
40	
41	/** Channels used when a recipient has never touched their preferences. */
42	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
43	
44	/**
45	 * Writes one notification row per recipient, each with the channel set that
46	 * recipient's preferences allow. A recipient who has muted every channel is
47	 * skipped entirely rather than given a row nobody will ever see.
48	 */
49	export async function notify(
50	  orgId: OrgId,
51	  kind: NotificationKind,
52	  recipients: readonly UserId[],
53	  payload: NotificationPayload,
54	): Promise<readonly Notification[]> {
55	  if (recipients.length === 0) return [];
56	
57	  const org = await orgRepo.findOrgById(orgId);
58	  const flags: FlagContext = {
59	    orgId,
60	    userId: payload.actorId,
61	    plan: org?.plan ?? "free",
62	    role: null,
63	    overrides: org?.settings.enabledFlagOverrides,
64	  };
65	
66	  const rows = [];
67	
68	  for (const recipientId of new Set(recipients)) {
69	    if (recipientId === payload.actorId) continue;
70	
71	    const preference = await preferenceRepo.getPreference(
72	      orgId,
73	      recipientId,
74	      kind,
75	    );
76	    const channels = resolveChannels(preference, flags);
77	    if (channels.length === 0) continue;
78	
79	    rows.push({
80	      orgId,
81	      recipientId,
82	      kind,
83	      title: payload.title,
84	      body: payload.body,
85	      href: payload.href,
86	      actorId: payload.actorId,
87	      channels,
88	    });
89	  }
90	
91	  return notificationRepo.insertNotifications(orgId, rows);
92	}
93	
94	export async function listNotifications(
95	  actor: Actor,
96	  input: ListNotificationsInput,
97	): Promise<Page<Notification>> {
98	  assertOrgScope(actor, input.orgId);
99	  assertCan(
100	    actor,
101	    "notification:read",
102	    notificationResource(input.orgId, input.recipientId),
103	  );
104	  return notificationRepo.listNotifications(input);
105	}
106	
107	export async function markRead(
108	  actor: Actor,
109	  input: MarkNotificationReadInput,
110	): Promise<Notification> {
111	  assertOrgScope(actor, input.orgId);
112	  assertCan(
113	    actor,
114	    "notification:manage",
115	    notificationResource(input.orgId, actor.userId),
116	  );
117	  return notificationRepo.markRead(
118	    input.orgId,
119	    actor.userId,
120	    input.notificationId,
121	    toIsoTimestamp(new Date()),
122	  );
123	}
124	
125	export async function markAllRead(
126	  actor: Actor,
127	  orgId: OrgId,
128	): Promise<number> {
129	  assertOrgScope(actor, orgId);
130	  assertCan(
131	    actor,
132	    "notification:manage",
133	    notificationResource(orgId, actor.userId),
134	  );
135	  return notificationRepo.markAllRead(
136	    orgId,
137	    actor.userId,
138	    toIsoTimestamp(new Date()),
139	  );
140	}
141	
142	export async function updatePreference(
143	  actor: Actor,
144	  input: UpdateNotificationPreferenceInput,
145	): Promise<NotificationPreference> {
146	  assertOrgScope(actor, input.orgId);
147	  assertCan(
148	    actor,
149	    "notification:manage",
150	    notificationResource(input.orgId, input.userId),
151	  );
152	  return preferenceRepo.upsertPreference(input);
153	}
154	
155	/**
156	 * Turns a stored preference into the channels one notification will use.
157	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
158	 * the email channel additionally requires the org's `digest_email` plan flag.
159	 */
160	export function resolveChannels(
161	  preference: NotificationPreference | null,
162	  flags: FlagContext,
163	): readonly NotificationChannel[] {
164	  if (preference === null) return DEFAULT_CHANNELS;
165	
166	  const channels: NotificationChannel[] = [];
167	  if (preference.inApp) channels.push("in_app");
168	
169	  const emailAllowed =
170	    preference.email &&
171	    (!preference.digestOnly || isEnabled("digest_email", flags));
172	
173	  if (emailAllowed) channels.push("email");
174	  return channels;
175	}
176	
177	/**
178	 * The bus wiring. Attached at module load rather than from `event-registry`
179	 * because the fan-out has no other public entry point — importing this module
180	 * is what makes an org start receiving notifications.
181	 */
182	let registered = false;
183	
184	/** Resolves an issue's link, falling back to the org root if it vanished. */
185	async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
186	  const org = await orgRepo.findOrgById(orgId);
187	  const issue = await issueRepo.findIssueById(orgId, issueId);
188	  if (!org || !issue) return "/";
189	
190	  const project = await projectRepo.findProjectById(orgId, issue.projectId);
191	  if (!project) return "/";
192	
193	  return issuePath(org.slug, project.slug, issue.number);
194	}
195	
196	/**
197	 * Only recipients without a still-unread alert for the same resource get a
198	 * new row; once that one is read, the next breach starts a fresh alert.
199	 */
200	async function notifyPlanLimit(
201	  orgId: OrgId,
202	  resource: string,
203	  recipients: readonly UserId[],
204	  payload: NotificationPayload,
205	): Promise<void> {
206	  const fresh: UserId[] = [];
207	  for (const recipientId of recipients) {
208	    const unread = await notificationRepo.listUnreadByKind(
209	      orgId,
210	      recipientId,
211	      "plan_limit_reached",
212	    );
213	    if (unread.some((n) => n.body.includes(resource))) continue;
214	    fresh.push(recipientId);
215	  }
216	  await notify(orgId, "plan_limit_reached", fresh, payload);
217	}
218	
219	function registerFanOut(): void {
220	  if (registered) return;
221	  registered = true;
222	
223	  subscribe("issue.assigned", async (payload) => {
224	    const href = await issueHref(payload.orgId, payload.issueId);
225	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
226	      title: "You were assigned an issue",
227	      body: `Issue ${payload.issueId} is now yours`,
228	      href,
229	      actorId: payload.actorId,
230	    });
231	  });
232	
233	  subscribe("issue.status_changed", async (payload) => {
234	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
235	    if (!issue || issue.assigneeId === null) return;
236	
237	    const href = await issueHref(payload.orgId, payload.issueId);
238	    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
239	      title: "Issue status changed",
240	      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
241	      href,
242	      actorId: payload.actorId,
243	    });
244	  });
245	
246	  subscribe("issue.overdue", async (payload) => {
247	    if (payload.assigneeId === null) return;
248	    const href = await issueHref(payload.orgId, payload.issueId);
249	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
250	      title: "An issue is overdue",
251	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
252	      href,
253	      actorId: null,
254	    });
255	  });
256	
257	  subscribe("comment.created", async (payload) => {
258	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
259	    const watchers = issue
